180	export async function storeMcpAppResultSnapshot(args: {
181		ctx: ToolContext;
182		toolCallId: unknown;
183		bindingCapability?: unknown;
184		toolName: string;
185		data: UnknownRecord;
186	}): Promise<boolean> {
