 44	type UnknownRecord = Record<string, unknown>;
 45	type ViewState = Record<string, boolean | number | string>;
 46	type ViewStateChange = (key: string, value: boolean | number | string) => void;
 47	
 48	function isRecord(value: unknown): value is UnknownRecord {
 49		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 50	}
 51	
 52	function humanize(value: string): string {
 53		return value
 54			.replace(/[_-]+/g, " ")
 55			.replace(/\b\w/g, (letter) => letter.toUpperCase());
 56	}
 57	
 58	function stringify(value: unknown): string {
 59		try {
 60			return JSON.stringify(value, null, 2);
 61		} catch {
 62			return String(value);
 63		}
 64	}
 65	
 66	function compactValue(value: unknown): string {
 67		if (value === null) return "null";
 68		if (value === undefined) return "—";
 69		if (typeof value === "string") return value;
 70		if (typeof value === "number" || typeof value === "boolean")
 71			return String(value);
 72		return stringify(value);
 73	}
